        public void ExportToExcel(DailyWinLoss2hParam param)
        {
            #region ExcelFormat

            const int startCol = 0;
            var currentRow = 0;
            var reportName = param.ReportFileName;
            var excelFile = new ExcelFile();
            var wsReport = excelFile.Worksheets.Add(param.DefaultSheetName.Replace("/", "_"));
            var dml2hReport = DailyWLDirect_Sporttype(param);
            var excelGemboxUtils = new ExcelGemboxUtils();

            var bgColor = Color.FromArgb(255, 255, 255);
            var commonStyle = excelGemboxUtils.GetStyleText(255, 255, 255);
            var bgFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, false, true);
            var bgFormatPercent = excelGemboxUtils.GetStyleIntNumber(".00%", bgColor, false, true);
            var bgLineTotalFormat = excelGemboxUtils.GetStyleIntNumber(".00", Color.FromArgb(130, 199, 255), true, true);
            var bgTurnoverFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, true, true);
            var numberDefaultFormat = GetStyleIntNumberLiveCasino(".00", Color.FromArgb(253, 252, 252), false, false);

            var evenRowColor = Color.FromArgb(205, 222, 243);
            var evenRowCommonStyle = excelGemboxUtils.GetStyleText(205, 222, 243);
            var evenRowFormat = excelGemboxUtils.GetStyleIntNumber(".00", evenRowColor, false, true);
            var evenRowFormatPercent = excelGemboxUtils.GetStyleIntNumber(".00%", evenRowColor, false, true);
            var evenRowTurnoverFormat = excelGemboxUtils.GetStyleIntNumber(".00", evenRowColor, true, true);
            var evenRowNumberDefaultFormat = GetStyleIntNumberLiveCasino(".00", evenRowColor, false, false);

            var ibcSuffix = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "IBCSuffix");
            ExcelCell currentCell;
            CellRange currentCellRange;
            var currentCol = startCol;
            var maxColIndex = 10;

            #endregion ExcelFormat
            #region Header

            var reportHeaderTitle = param.ReportTitle;
            ExportMainReportHeader(ref wsReport, startCol, ref currentRow, reportHeaderTitle);

            #endregion Header
            #region Body

            if (dml2hReport != null && dml2hReport.ReportDetails.Count > 0)
            {
                var isChange_ApplyVirtualRateType = false;
                var detailLength = dml2hReport.ReportDetails.Count;
                for (var i = 0; i < detailLength; i++)
                {
                    var item = dml2hReport.ReportDetails[i];
                    if (item.RowTypeDWL2h.Id == 0 &&
                        !item.IsApplyVirtualRate &&
                        !isChange_ApplyVirtualRateType)
                    {
                        var total = dml2hReport.ReportTotal;

                        #region NormalTotal

                        var normalTotal = total.NormalTotal;
                        currentCol = startCol;
                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowCommonStyle;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                        currentCell.Value = Labels.Virtual_All_Total;
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.WinLoss);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowNumberDefaultFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.Position);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowNumberDefaultFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.Commission);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.LineTotal);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.LineTotalVirtual);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.Variance);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowNumberDefaultFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.Turnover);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowNumberDefaultFormat;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                        currentCell.Value = CastAide.AsDecimal(normalTotal.TurnoverVirtual);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowFormatPercent;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        if (CastAide.AsDouble(normalTotal.Turnover) != 0)
                        {
                            currentCell.Value = CastAide.AsDouble(normalTotal.Margin) / 100;
                        }
                        else
                        {
                            currentCell.Value = "N/A";
                        }

                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = evenRowFormatPercent;
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                        if (CastAide.AsDouble(normalTotal.TurnoverVirtual) != 0)
                        {
                            currentCell.Value = CastAide.AsDouble(normalTotal.MarginVirtual) / 100;
                        }
                        else
                        {
                            currentCell.Value = "N/A";
                        }

                        currentCol++;
                        currentRow++;

                        #endregion NormalTotal
                        #region IBCTotal

                        var soccerEightRM = total.SoccerEightRMTotal;
                        if (soccerEightRM != null &&
                            (soccerEightRM.LineTotal != 0 || soccerEightRM.LineTotalVirtual != 0))
                        {
                            currentCol = startCol;
                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = evenRowCommonStyle;
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                            currentCell.Value = soccerEightRM.AliasName;
                            currentCol++;

                            currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 2);
                            currentCellRange.Style = evenRowCommonStyle;
                            currentCellRange.Merged = true;
                            currentCol += 3;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = evenRowFormat;
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(soccerEightRM.LineTotal);
                            currentCol++;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = evenRowFormat;
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(soccerEightRM.LineTotalVirtual);
                            currentCol++;

                            currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 4);
                            currentCellRange.Style = evenRowCommonStyle;
                            currentCellRange.Merged = true;
                            currentCol += 5;
                            currentRow++;
                        }

                        var soccerBARM = total.SoccerBARMTotal;
                        if (_barmConfig.IsActive &&
                            soccerBARM != null &&
                            (soccerBARM.LineTotal != 0 || soccerBARM.LineTotalVirtual != 0))
                        {
                            currentCol = startCol;
                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = evenRowCommonStyle;
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
                            currentCell.Value = soccerBARM.AliasName;
                            currentCol++;

                            currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 2);
                            currentCellRange.Style = evenRowCommonStyle;
                            currentCellRange.Merged = true;
                            currentCol += 3;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = evenRowFormat;
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(soccerBARM.LineTotal);
                            currentCol++;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = evenRowFormat;
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(soccerBARM.LineTotalVirtual);
                            currentCol++;

                            currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 4);
                            currentCellRange.Style = evenRowCommonStyle;
                            currentCellRange.Merged = true;
                            currentCol += 5;
                            currentRow++;
                        }

                        #endregion IBCTotal

                        this.ExportEmptyRow(ref wsReport, ref currentRow, startCol, startCol + maxColIndex);
                    }

                    switch (item.RowTypeDWL2h.Id)
                    {
                        case RowTypeConstants.Normal:
                            currentCol = startCol;
                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = (item.IsApplyVirtualRate ? evenRowCommonStyle : commonStyle);
                            currentCell.Value = item.Name;
                            currentCol++;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = (item.IsApplyVirtualRate ? evenRowFormat : bgFormat);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(item.WinLoss);
                            currentCol++;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = (item.IsApplyVirtualRate ? evenRowNumberDefaultFormat : numberDefaultFormat);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(item.Position);
                            currentCol++;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = (item.IsApplyVirtualRate ? evenRowNumberDefaultFormat : numberDefaultFormat);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(item.Commission);
                            currentCol++;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = (item.IsApplyVirtualRate ? evenRowFormat : bgFormat);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDecimal(item.LineTotal);
                            currentCol++;

                            if (item.IsApplyVirtualRate)
                            {
                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.LineTotalVirtual);
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.Variance);
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = (item.IsApplyVirtualRate ? evenRowNumberDefaultFormat : numberDefaultFormat);
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.Turnover);
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = (item.IsApplyVirtualRate ? evenRowNumberDefaultFormat : numberDefaultFormat);
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.TurnoverVirtual);
                                currentCol++;
                            }
                            else
                            {
                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = bgFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = "N/A";
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = bgFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = "N/A";
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = (item.IsApplyVirtualRate ? evenRowNumberDefaultFormat : numberDefaultFormat);
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.Turnover);
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = (item.IsApplyVirtualRate ? evenRowNumberDefaultFormat : numberDefaultFormat);
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = "N/A";
                                currentCol++;
                            }

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = (item.IsApplyVirtualRate ? evenRowFormatPercent : bgFormatPercent);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            if (CastAide.AsDouble(item.Turnover) != 0)
                            {
                                currentCell.Value = CastAide.AsDouble(item.Margin) / 100;
                            }
                            else
                            {
                                currentCell.Value = "N/A";
                            }

                            currentCol++;

                            currentCell = wsReport.Cells[currentRow, currentCol];
                            currentCell.Style = (item.IsApplyVirtualRate ? evenRowFormatPercent : bgFormatPercent);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            if (CastAide.AsDouble(item.TurnoverVirtual) != 0)
                            {
                                currentCell.Value = CastAide.AsDouble(item.MarginVirtual) / 100;
                            }
                            else
                            {
                                currentCell.Value = "N/A";
                            }

                            currentCol++;
                            currentRow++;
                            break;
                        case RowTypeConstants.EightRM:
                            if (item.Id != Sports.Soccer)
                            {
                                currentCol = startCol;
                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowCommonStyle;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Left;
                                currentCell.Value = item.AliasName;
                                currentCol++;

                                currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 2);
                                currentCellRange.Style = evenRowCommonStyle;
                                currentCellRange.Merged = true;
                                currentCol += 3;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.LineTotal);
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.LineTotalVirtual);
                                currentCol++;

                                currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 4);
                                currentCellRange.Style = evenRowCommonStyle;
                                currentCellRange.Merged = true;
                                currentCol += 5;
                                currentRow++;
                            }
                            break;
                        case RowTypeConstants.BARM:
                            if (_barmConfig.IsActive && item.Id != Sports.Soccer)
                            {
                                currentCol = startCol;
                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowCommonStyle;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Left;
                                currentCell.Value = item.AliasName;
                                currentCol++;

                                currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 2);
                                currentCellRange.Style = evenRowCommonStyle;
                                currentCellRange.Merged = true;
                                currentCol += 3;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.LineTotal);
                                currentCol++;

                                currentCell = wsReport.Cells[currentRow, currentCol];
                                currentCell.Style = evenRowFormat;
                                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                                currentCell.Value = CastAide.AsDecimal(item.LineTotalVirtual);
                                currentCol++;

                                currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, currentCol, currentRow, currentCol + 4);
                                currentCellRange.Style = evenRowCommonStyle;
                                currentCellRange.Merged = true;
                                currentCol += 5;
                                currentRow++;
                            }
                            break;
                        case RowTypeConstants.SportTotal:
                            break;
                        case RowTypeConstants.EmptyRow:
                            var nextInfoIndex = i < detailLength - 1 ? i + 1 : i;
                            var nextInfo = dml2hReport.ReportDetails[nextInfoIndex];
                            if (isChange_ApplyVirtualRateType ||
                                nextInfo.IsApplyVirtualRate)
                            {
                                this.ExportEmptyRow(ref wsReport, ref currentRow, startCol, startCol + maxColIndex);
                            }

                            break;
                    }

                    if (item.RowTypeDWL2h.Id == 0 &&
                       !item.IsApplyVirtualRate &&
                       !isChange_ApplyVirtualRateType)
                    {
                        isChange_ApplyVirtualRateType = true;
                    }
                }

                ExportMainReportFooter(ref wsReport, dml2hReport, startCol, ref currentRow);
            }
            else
            {
                this.ExportEmptyReport(ref wsReport, ref currentRow, startCol, startCol + maxColIndex);
            }

            #endregion Body

            ReportService.RespondStream(excelFile, reportName);
        }

