        private bool IsExcludeFromGrandTotal(int sporttype)
        {
            return sporttype == Constants.Sports.HorseRacing ||
                   sporttype == Constants.Sports.Casino ||
                   sporttype == Constants.Sports.BingoGame ||
                   sporttype == Constants.Sports.VirtualSports ||
                   sporttype == Constants.Sports.P2P ||
                   sporttype == Constants.Sports.LiveCasino;
        }

        private string GetBetTypeName(DailyWinLoss2hItem dwl2hItem)
        {
            string bettypeName = dwl2hItem.Bettype.Name;

            if (string.IsNullOrEmpty(dwl2hItem.Bettype.Name))
            {
                switch (dwl2hItem.Bettype.Id)
                {
                    case 71:
                        bettypeName = "Casino";
                        break;
                    case 72:
                        bettypeName = "P2P";
                        break;
                    case 252:
                        bettypeName = "IBCbet Bingo";
                        break;
                }
            }

            if (!string.IsNullOrEmpty(dwl2hItem.Hedge) && dwl2hItem.Hedge.Contains("(hedge)"))
            {
                switch (dwl2hItem.Bettype.Id)
                {
                    case 1:
                        bettypeName = "HDP (hedge)";
                        break;
                    case 3:
                        bettypeName = "OU (hedge)";
                        break;
                    case 7:
                        bettypeName = "1st HDP (hedge)";
                        break;
                    case 8:
                        bettypeName = "1st OU (hedge)";
                        break;
                }
            }
            else
            {
                switch (dwl2hItem.Bettype.Id)
                {
                    case 1:
                        bettypeName = "HDP";
                        break;
                    case 3:
                        bettypeName = "OU";
                        break;
                    case 4:
                        bettypeName = "CS";
                        break;
                    case 30:
                        bettypeName = "1st CS";
                        break;
                    case 6:
                        bettypeName = "TG";
                        break;
                    case 7:
                        bettypeName = "1st HDP";
                        break;
                    case 8:
                        bettypeName = "1st OU";
                        break;
                    case 14:
                        bettypeName = "FG/LG";
                        break;
                    case 1001:
                        bettypeName = "Kick Off";
                        break;
                    default:
                        break;
                }
            }

            return bettypeName;
        }

